-- =============================================================================
-- GovernIT Data Eraser - migration 004: store original certificate PDFs.
-- =============================================================================
-- The downloadable certificate on the web portal was previously re-rendered
-- on the fly with a separate PHP layout. This migration stores the actual
-- PDF bytes generated by the Boot system (uploaded during result sync) so the
-- website serves the authentic certificate layout.

ALTER TABLE certificate ADD COLUMN pdf_bytes LONGBLOB NULL AFTER certificate_hash;
ALTER TABLE certificate ADD COLUMN pdf_filename VARCHAR(255) NULL AFTER pdf_bytes;